/*
 * High-performance portfolio calculations using C extension
 *
 * portfolio_risk   = sqrt(x^T * S * x)
 * portfolio_return = x^T * r
 *
 * Uses the NumPy C API for zero-copy access to contiguous float64 arrays.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/*
 * Convert an arbitrary input object into a C-contiguous, native-endian
 * float64 ndarray.  If the input already is one, no data is copied.
 */
static PyArrayObject* as_f64_contiguous(PyObject *obj, const char *name) {
    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(
        obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (arr == NULL) {
        PyErr_Format(PyExc_TypeError,
                     "%s could not be converted to a float64 array", name);
        return NULL;
    }
    return arr;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    PyArrayObject *weights_array = as_f64_contiguous(weights_obj, "weights");
    if (weights_array == NULL)
        return NULL;

    PyArrayObject *cov_array = as_f64_contiguous(cov_obj, "cov_matrix");
    if (cov_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be a 1D array");
        goto fail;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be a 2D array");
        goto fail;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be an n x n matrix matching weights");
        goto fail;
    }

    const double *restrict x = (const double *)PyArray_DATA(weights_array);
    const double *restrict s = (const double *)PyArray_DATA(cov_array);

    /*
     * Step 1: temp = S * x, accumulated in index order just like the
     * Python baseline.  Step 2: risk_squared = x . temp.
     * Fusing the two steps avoids materialising temp and is
     * mathematically identical.
     */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *restrict row = s + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += row[j] * x[j];
        risk_squared += x[i] * row_sum;
    }

    Py_DECREF(weights_array);
    Py_DECREF(cov_array);

    if (risk_squared < 0.0)
        risk_squared = 0.0;
    return PyFloat_FromDouble(sqrt(risk_squared));

fail:
    Py_DECREF(weights_array);
    Py_DECREF(cov_array);
    return NULL;
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    PyArrayObject *weights_array = as_f64_contiguous(weights_obj, "weights");
    if (weights_array == NULL)
        return NULL;

    PyArrayObject *returns_array = as_f64_contiguous(returns_obj,
                                                     "expected_returns");
    if (returns_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must be 1D arrays");
        goto fail;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have equal length");
        goto fail;
    }

    const double *restrict x = (const double *)PyArray_DATA(weights_array);
    const double *restrict r = (const double *)PyArray_DATA(returns_array);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += x[i] * r[i];

    Py_DECREF(weights_array);
    Py_DECREF(returns_array);
    return PyFloat_FromDouble(total_return);

fail:
    Py_DECREF(weights_array);
    Py_DECREF(returns_array);
    return NULL;
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}
EOF

