/*
 * High-performance portfolio calculations using C extension
 *
 * portfolio_risk   = sqrt(x^T * S * x)
 * portfolio_return = x^T * r
 *
 * Two data paths:
 *   1. Fast path for nested Python sequences (list/tuple of list/tuple of
 *      numbers, i.e. exactly what the baseline produces).  The matrix is
 *      traversed in place, which avoids numpy's costly generic
 *      nested-sequence conversion and a full copy of the n x n matrix.
 *   2. Generic path for anything else, via the NumPy C API with
 *      zero-copy access to C-contiguous float64 arrays.
 *
 * Both paths accumulate in the same order as the Python baseline:
 *   temp[i] = sum_j cov[i][j] * x[j],  risk^2 = sum_i x[i] * temp[i].
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

/* ---------- small sequence helpers ---------- */

static inline int is_seq(PyObject *o) {
    return PyList_Check(o) || PyTuple_Check(o);
}

static inline Py_ssize_t seq_len(PyObject *o) {
    return PyList_Check(o) ? PyList_GET_SIZE(o) : PyTuple_GET_SIZE(o);
}

static inline PyObject *seq_item(PyObject *o, Py_ssize_t i) {
    return PyList_Check(o) ? PyList_GET_ITEM(o, i) : PyTuple_GET_ITEM(o, i);
}

/* Convert one Python object to a double.  Returns 0 on success, -1 on error. */
static inline int to_double(PyObject *item, double *out) {
    if (PyFloat_CheckExact(item)) {
        *out = PyFloat_AS_DOUBLE(item);
        return 0;
    }
    double v = PyFloat_AsDouble(item);
    if (v == -1.0 && PyErr_Occurred())
        return -1;
    *out = v;
    return 0;
}

/* Copy a 1D Python sequence of numbers into a freshly malloc'd buffer. */
static int seq_to_doubles(PyObject *obj, Py_ssize_t *n_out, double **buf_out) {
    Py_ssize_t n = seq_len(obj);
    double *buf = (double *)malloc(sizeof(double) * (size_t)(n > 0 ? n : 1));
    if (buf == NULL) {
        PyErr_NoMemory();
        return -1;
    }
    for (Py_ssize_t i = 0; i < n; ++i) {
        if (to_double(seq_item(obj, i), &buf[i]) < 0) {
            free(buf);
            return -1;
        }
    }
    *n_out = n;
    *buf_out = buf;
    return 0;
}

/*
 * Fast path for portfolio risk with a nested-sequence covariance matrix.
 * Writes the result to *result and returns 1 if handled, 0 if the inputs are
 * not in the expected form (caller should use the generic path), -1 on error.
 */
static int risk_fast_path(PyObject *w_obj, PyObject *cov_obj,
                          PyObject **result) {
    if (!is_seq(cov_obj))
        return 0;

    const Py_ssize_t n = seq_len(cov_obj);
    double *x = NULL;

    if (is_seq(w_obj)) {
        Py_ssize_t wn;
        if (seq_to_doubles(w_obj, &wn, &x) < 0)
            return -1;
        if (wn != n) {
            free(x);
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be an n x n matrix matching weights");
            return -1;
        }
    } else if (PyArray_Check(w_obj)) {
        PyArrayObject *wa = (PyArrayObject *)PyArray_FROM_OTF(
            w_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (wa == NULL)
            return -1;
        if (PyArray_NDIM(wa) != 1 || PyArray_DIM(wa, 0) != n) {
            Py_DECREF(wa);
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be an n x n matrix matching weights");
            return -1;
        }
        x = (double *)malloc(sizeof(double) * (size_t)(n > 0 ? n : 1));
        if (x == NULL) {
            Py_DECREF(wa);
            PyErr_NoMemory();
            return -1;
        }
        memcpy(x, PyArray_DATA(wa), sizeof(double) * (size_t)n);
        Py_DECREF(wa);
    } else {
        return 0;
    }

    /* Validate the matrix shape before touching any elements. */
    for (Py_ssize_t i = 0; i < n; ++i) {
        PyObject *row = seq_item(cov_obj, i);
        if (!is_seq(row) || seq_len(row) != n) {
            free(x);
            return 0;   /* let the generic path produce the proper result/error */
        }
    }

    /*
     * Fused S*x then x.(S*x).  Row sums are accumulated in index order,
     * matching the baseline's arithmetic exactly.
     */
    double risk_squared = 0.0;
    for (Py_ssize_t i = 0; i < n; ++i) {
        PyObject *row = seq_item(cov_obj, i);
        double row_sum = 0.0;
        if (PyList_Check(row)) {
            for (Py_ssize_t j = 0; j < n; ++j) {
                PyObject *item = PyList_GET_ITEM(row, j);
                double v;
                if (PyFloat_CheckExact(item)) {
                    v = PyFloat_AS_DOUBLE(item);
                } else if (to_double(item, &v) < 0) {
                    free(x);
                    return -1;
                }
                row_sum += v * x[j];
            }
        } else {
            for (Py_ssize_t j = 0; j < n; ++j) {
                PyObject *item = PyTuple_GET_ITEM(row, j);
                double v;
                if (PyFloat_CheckExact(item)) {
                    v = PyFloat_AS_DOUBLE(item);
                } else if (to_double(item, &v) < 0) {
                    free(x);
                    return -1;
                }
                row_sum += v * x[j];
            }
        }
        risk_squared += x[i] * row_sum;
    }
    free(x);

    if (risk_squared < 0.0)
        risk_squared = 0.0;
    *result = PyFloat_FromDouble(sqrt(risk_squared));
    return *result != NULL ? 1 : -1;
}

/* Fast path for portfolio return with Python sequences. */
static int return_fast_path(PyObject *w_obj, PyObject *r_obj,
                            PyObject **result) {
    if (!is_seq(w_obj) || !is_seq(r_obj))
        return 0;

    const Py_ssize_t n = seq_len(w_obj);
    if (seq_len(r_obj) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have equal length");
        return -1;
    }

    double total = 0.0;
    for (Py_ssize_t i = 0; i < n; ++i) {
        double w, r;
        if (to_double(seq_item(w_obj, i), &w) < 0)
            return -1;
        if (to_double(seq_item(r_obj, i), &r) < 0)
            return -1;
        total += w * r;
    }
    *result = PyFloat_FromDouble(total);
    return *result != NULL ? 1 : -1;
}

/* ---------- generic NumPy path ---------- */

static PyArrayObject *as_f64_contiguous(PyObject *obj) {
    return (PyArrayObject *)PyArray_FROM_OTF(obj, NPY_DOUBLE,
                                             NPY_ARRAY_IN_ARRAY);
}

static PyObject *risk_numpy_path(PyObject *w_obj, PyObject *cov_obj) {
    PyArrayObject *weights_array = as_f64_contiguous(w_obj);
    if (weights_array == NULL)
        return NULL;

    PyArrayObject *cov_array = as_f64_contiguous(cov_obj);
    if (cov_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be a 1D array");
        goto fail;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be a 2D array");
        goto fail;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be an n x n matrix matching weights");
        goto fail;
    }

    const double *restrict x = (const double *)PyArray_DATA(weights_array);
    const double *restrict s = (const double *)PyArray_DATA(cov_array);

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *restrict row = s + (npy_intp)i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += row[j] * x[j];
        risk_squared += x[i] * row_sum;
    }

    Py_DECREF(weights_array);
    Py_DECREF(cov_array);

    if (risk_squared < 0.0)
        risk_squared = 0.0;
    return PyFloat_FromDouble(sqrt(risk_squared));

fail:
    Py_DECREF(weights_array);
    Py_DECREF(cov_array);
    return NULL;
}

static PyObject *return_numpy_path(PyObject *w_obj, PyObject *r_obj) {
    PyArrayObject *weights_array = as_f64_contiguous(w_obj);
    if (weights_array == NULL)
        return NULL;

    PyArrayObject *returns_array = as_f64_contiguous(r_obj);
    if (returns_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must be 1D arrays");
        goto fail;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have equal length");
        goto fail;
    }

    const double *restrict x = (const double *)PyArray_DATA(weights_array);
    const double *restrict r = (const double *)PyArray_DATA(returns_array);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += x[i] * r[i];

    Py_DECREF(weights_array);
    Py_DECREF(returns_array);
    return PyFloat_FromDouble(total_return);

fail:
    Py_DECREF(weights_array);
    Py_DECREF(returns_array);
    return NULL;
}

/* ---------- Python entry points ---------- */

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *w_obj, *cov_obj;
    if (!PyArg_ParseTuple(args, "OO", &w_obj, &cov_obj))
        return NULL;

    PyObject *result = NULL;
    int status = risk_fast_path(w_obj, cov_obj, &result);
    if (status != 0)
        return result;          /* 1: handled, -1: error (result == NULL) */

    return risk_numpy_path(w_obj, cov_obj);
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *w_obj, *r_obj;
    if (!PyArg_ParseTuple(args, "OO", &w_obj, &r_obj))
        return NULL;

    PyObject *result = NULL;
    int status = return_fast_path(w_obj, r_obj, &result);
    if (status != 0)
        return result;

    return return_numpy_path(w_obj, r_obj);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}
